/* @autogenerated */
import { ChangeDetectionStrategy, Component, computed, inject, Signal, signal } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { toSignal } from '@angular/core/rxjs-interop';
import { MAT_DIALOG_DATA, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatRadioModule } from '@angular/material/radio';
import { MatSlideToggleModule } from '@angular/material/slide-toggle';
import { TranslocoPipe, TranslocoService } from '@jsverse/transloco';
import { catchError, isObservable, map, of } from 'rxjs';
import { ConflictField, EditConflict, FieldMerge, FieldMergeChoice, FieldMergeState } from './edit-conflict.model';
import { applyMerge, chooseMerge, hasPendingConflicts, threeWayMerge } from './three-way-merge';

export interface EditConflictDialogData<T> {
  conflict: EditConflict<T>;
  fields: ConflictField[];
}

/** Texto a pintar: literal o clave de traducción. */
export type ConflictText = { text: string } | { key: string };

interface ConflictRow {
  field: string;
  /** Id del nombre del campo: los radios lo usan como `aria-labelledby`. */
  id: string;
  label: ConflictText;
  original: Signal<ConflictText>;
  sent: Signal<ConflictText>;
  current: Signal<ConflictText>;
}

const STATE_ICONS: Record<FieldMergeState, string> = {
  conflict: 'warning',
  mine: 'person',
  theirs: 'cloud',
  same: 'done_all',
  unchanged: 'remove',
};

const EMPTY_TEXT: ConflictText = { key: 'editConflict.empty' };

@Component({
  selector: 'edit-conflict-dialog',
  standalone: true,
  imports: [
    MatDialogModule,
    MatButtonModule,
    MatIconModule,
    MatRadioModule,
    MatSlideToggleModule,
    NgTemplateOutlet,
    TranslocoPipe,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './edit-conflict-dialog.component.html',
  styleUrl: './edit-conflict-dialog.component.scss',
})
export class EditConflictDialogComponent<T> {
  private readonly data = inject<EditConflictDialogData<T>>(MAT_DIALOG_DATA);
  private readonly dialogRef = inject<MatDialogRef<EditConflictDialogComponent<T>, T | null>>(MatDialogRef);
  private readonly transloco = inject(TranslocoService);

  readonly icons = STATE_ICONS;
  readonly merges = signal<FieldMerge[]>(this.sortedMerges());
  readonly rows = new Map<string, ConflictRow>(this.merges().map((merge) => [merge.field, this.row(merge)]));
  readonly showUnchanged = signal(false);

  readonly visible = computed(() =>
    this.merges().filter((merge) => this.showUnchanged() || merge.state !== 'unchanged'),
  );
  readonly conflicts = computed(() => this.merges().filter((merge) => merge.state === 'conflict').length);
  readonly autoMerged = computed(
    () => this.merges().filter((merge) => merge.state !== 'conflict' && merge.state !== 'unchanged').length,
  );
  readonly unchanged = computed(() => this.merges().filter((merge) => merge.state === 'unchanged').length);
  readonly pending = computed(() => hasPendingConflicts(this.merges()));
  /** Primer campo en conflicto: recibe el foco inicial. */
  readonly firstConflict = this.merges().find((merge) => merge.state === 'conflict')?.field;

  choose(field: string, choice: FieldMergeChoice) {
    this.merges.update((all) => all.map((merge) => (merge.field === field ? chooseMerge(merge, choice) : merge)));
  }

  /** Mis cambios ganan en los conflictos; lo que solo cambió el servidor se conserva. */
  keepMine() {
    this.merges.update((all) =>
      all.map((merge) => (merge.state === 'conflict' || merge.state === 'mine' ? chooseMerge(merge, 'sent') : merge)),
    );
  }

  /** Se descarta todo lo enviado: queda el valor actual del servidor. */
  useServer() {
    this.merges.update((all) => all.map((merge) => chooseMerge(merge, 'current')));
  }

  apply() {
    if (!this.pending()) {
      this.dialogRef.close(applyMerge(this.data.conflict, this.merges()));
    }
  }

  cancel() {
    this.dialogRef.close(null);
  }

  /** Campos en el orden de `fields`; los que no aparecen en él, al final. */
  private sortedMerges(): FieldMerge[] {
    const order = this.data.fields.map((field) => field.name);
    const position = (field: string) => (order.includes(field) ? order.indexOf(field) : order.length);
    return threeWayMerge(this.data.conflict).sort((a, b) => position(a.field) - position(b.field));
  }

  private row(merge: FieldMerge): ConflictRow {
    const field = this.data.fields.find((candidate) => candidate.name === merge.field);
    const text = (value: unknown) => this.display(value, field);
    return {
      field: merge.field,
      id: 'edit-conflict-field-' + merge.field,
      label: field ? { key: field.label + '.label' } : { text: merge.field },
      original: text(merge.original),
      sent: text(merge.sent),
      current: text(merge.current),
    };
  }

  private display(value: unknown, field?: ConflictField): Signal<ConflictText> {
    if (isBlank(value)) {
      return signal(EMPTY_TEXT);
    }
    const fallback = this.format(value);
    if (!field?.display) {
      return signal(fallback);
    }
    const shown = field.display(value);
    if (!isObservable(shown)) {
      return signal({ text: shown });
    }
    return toSignal(
      shown.pipe(
        map((text): ConflictText => ({ text })),
        // Sin etiqueta (la referencia ya no existe, sin permisos…) se muestra el valor tal cual
        catchError(() => of(fallback)),
      ),
      { initialValue: fallback },
    );
  }

  private format(value: unknown): ConflictText {
    if (typeof value === 'boolean') {
      return { key: value ? 'editConflict.yes' : 'editConflict.no' };
    }
    if (value instanceof Date) {
      return { text: value.toLocaleString(this.transloco.getActiveLang()) };
    }
    if (Array.isArray(value)) {
      return { text: value.map((item) => textOf(this.format(item))).join(', ') };
    }
    if (typeof value === 'object' && value !== null) {
      const ref = (value as { $ref?: unknown }).$ref;
      return { text: ref !== undefined ? String(ref) : JSON.stringify(value) };
    }
    return { text: String(value) };
  }
}

function isBlank(value: unknown): boolean {
  return value === null || value === undefined || value === '' || (Array.isArray(value) && value.length === 0);
}

function textOf(text: ConflictText): string {
  return 'text' in text ? text.text : text.key;
}
